    let img = (chunk.match(/<img[^>]*?\bclass="[^"]*\bs-image\b[^"]*"[^>]*?\bsrc="([^"]+)"/i) || [])[1] || (chunk.match(/<img[^>]*?\bsrc="([^"]+)"[^>]*?\bclass="[^"]*\bs-image\b/i) || [])[1] || null;
